class Solution {
 long long calc(vector<int>& a,int k,bool mx){int n=a.size();vector<int>L(n),R(n),st;
 for(int i=0;i<n;++i){while(!st.empty()&&(mx?a[st.back()]<=a[i]:a[st.back()]>=a[i]))st.pop_back();L[i]=st.empty()?i+1:i-st.back();st.push_back(i);}st.clear();
 for(int i=n-1;i>=0;--i){while(!st.empty()&&(mx?a[st.back()]<a[i]:a[st.back()]>a[i]))st.pop_back();R[i]=st.empty()?n-i:st.back()-i;st.push_back(i);}
 long long ans=0;for(int i=0;i<n;++i){long long l=min(L[i],k),r=min(R[i],k),z=k-1;long long count=l*r;
 // Count pairs (left length,right length) whose sum exceeds k+1.
 // Subtract pairs of lengths whose sum exceeds k+1.
 long long a0=max(1LL,(long long)k-r+2),a1=l;
 if(a0<=a1){long long c=a1-a0+1;count=l*r-c*(a0+a1+2*r-2*k-2)/2;}
 ans+=count*a[i];}return ans;}
 public:long long minMaxSubarraySum(vector<int>& nums,int k){return calc(nums,k,true)+calc(nums,k,false);}
};
